def result_state(g,result):
    expected=result.get('input_fingerprints',{})
    if result.get('fragment_version') and result['fragment_version']!=formalcheck.VERSION:return 'stale'
    if not expected or result.get('checker_version')!=CHECKER_VERSION:return 'stale'
    if any(fingerprint(g.get(key,{}))!=expected for key,expected in result.get('definition_fingerprints',{}).items()): return 'stale'
    if result.get('provenance_roots') and provenance(g,result['provenance_roots']) != result.get('provenance'): return 'stale'
    return 'current' if all((i not in g['nodes'] if f is None else i in g['nodes'] and fingerprint(g['nodes'][i])==f) for i,f in expected.items()) else 'stale'

def evaluations(g,node_id=None):
    found=[]
    for i,n in g['nodes'].items():
        if n.get('type')!='check-result' or not isinstance(n.get('result'),dict):continue
        r=n['result']
        if node_id and node_id not in (i,r.get('claim'),r.get('trace')):continue
        found.append({'id':i,**r,'result_state':result_state(g,r)})
    return {'revision':g['revision'],'results':found}

def annotate(g,response):
    """Attach derived freshness on response copies only, never canonical writes."""
    if isinstance(response.get('nodes'),dict):
        response={**response,'nodes':{i:{**n,**({'result_state':result_state(g,n['result'])} if n.get('type')=='check-result' and isinstance(n.get('result'),dict) else {})} for i,n in response['nodes'].items()}}
    elif response.get('type')=='check-result' and isinstance(response.get('result'),dict):
        response={**response,'result_state':result_state(g,response['result'])}
    return response


def coverage(g, claim_id):
    """Distinguish evidence links, current receipts, stale receipts and mere topics.

    `tests`/`supports` go evidence -> claim; `tested-by` goes claim -> evidence.
    Custom relations must declare coverage direction explicitly. A bounded check
    receipt is not proof or empirical occurrence; keep its outcome/synthetic flag.
    """
    evidence=[]; current=[]; stale=[]; unchecked=[]
    def active(node):
        return node.get('status') not in ('withdrawn','rejected','retired','superseded') and (node.get('meta') or {}).get('review_state')!='historical'
    for eid,edge in sorted(g.get('edges',{}).items()):
        relation=edge.get('type');decl=g.get('edge_types',{}).get(relation,{})
        direction=decl.get('coverage')
        if relation in ('tests','supports'):direction='evidence-to-claim'
        elif relation=='tested-by':direction='claim-to-evidence'
        target=None
        if direction=='evidence-to-claim' and edge.get('to')==claim_id:target=edge.get('from')
        elif direction=='claim-to-evidence' and edge.get('from')==claim_id:target=edge.get('to')
        node=g.get('nodes',{}).get(target,{})
        if node.get('type') in ('case','trace') and active(node):
            evidence.append({'edge':eid,'evidence':target,'relation':relation,'synthetic':bool((node.get('meta') or {}).get('synthetic')),'evaluation':'not-implied'})
    for rid,node in sorted(g.get('nodes',{}).items()):
        result=node.get('result',{})
        if node.get('type')!='check-result' or not isinstance(result,dict) or result.get('claim')!=claim_id or not active(node):continue
        trace=g.get('nodes',{}).get(result.get('trace'),{})
        item={'id':rid,'trace':result.get('trace'),'outcome':result.get('outcome'),'synthetic':bool(result.get('synthetic')),'checked_events':result.get('checked_events',[]),'scope':result.get('scope')}
        if result_state(g,result)!='current':stale.append(item)
        elif trace.get('type')!='trace' or not active(trace) or result.get('outcome') not in ('satisfies','violates','insufficient-information'):unchecked.append(item)
        else:current.append(item)
    return {'claim':claim_id,'has_coverage':bool(evidence or current),
            'state':'evaluated' if current else 'declared-evidence' if evidence else 'none',
            'declared_evidence':evidence,'current_evaluations':current,'stale_evaluations':stale,'unchecked_evaluations':unchecked,
            'scope':'Coverage records bounded evaluations or explicitly linked cases. It does not imply completeness, truth of extraction, or historical occurrence.'}
